builder.Entity<ReviewState>()
    .HasIndex(x => new { x.UserId, x.DueAt });

-- Index: IX_ReviewState_UserId_DueAt (UserId, DueAt)

-- Seek on both columns, rows already ordered by DueAt:
SELECT Id FROM ReviewStates WHERE UserId = @u AND DueAt <= @now ORDER BY DueAt;

-- Seek on UserId only; Grade is filtered row by row:
SELECT Id FROM ReviewStates WHERE UserId = @u AND Grade < 3;

-- Cannot seek: DueAt is not a leftmost prefix. Needs its own index or a scan.
SELECT Id FROM ReviewStates WHERE DueAt <= @now;
